  (* [comment removed for export] *)
  Lemma pn_B : forall regs m (s h pix : Z) (v : pixv),
    PIXat m pix v -> p_h v = h -> (1 <= h <= 20000)%Z -> (1 <= p_wpl v <= 20000)%Z -> (4096 <= pix)%Z ->
    rdn SEGS m (rl dA_1f430 0x1f430) 8 = Some (Z_to_le_bytes 8 (0x15b3c + dF_15b3c)) ->
    getr regs 10 = Z_to_bv 64 pix -> getr regs 9 = Z_to_bv 64 h ->
    exists regs',
      msteps SEGS (mkst regs (rl dOL_237ac 0x237c8) m rom) (mkst regs' (rl dF_15b3c 0x15b3c) m rom)
      /\ getr regs' 10 = Z_to_bv 64 (4 * (p_wpl v * h)) /\ getr regs' 1 = rl dOL_237ac 0x237ec /\ getr regs' 8 = Z_to_bv 64 pix
      /\ getr regs' 18 = rl dA_1f430 0x1f430
      /\ regs_agree (fun r => In r [1; 8; 10; 11; 18]%list) regs regs'.
Proof.
